    </>
  );

  if (to) {
    return (
      <Link to={to} className="flex items-center gap-4 p-4 hover:bg-gray-50 transition">
        {content}
      </Link>
    );
  }

  return (
    <button onClick={onClick} className="w-full flex items-center gap-4 p-4 hover:bg-gray-50 transition text-left">
      {content}
    </button>
  );
};

