import React, { useState, useRef, useEffect } from 'react';
import { Product, ADMIN_EMAILS } from '../types';
import { useStore } from '../store/useStore';
import { ShoppingBag, Heart, Trash2, Loader2, MoreVertical, Edit } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useNavigate } from 'react-router-dom';

interface ProductCardProps {
  product: Product;
  onDelete?: (id: string) => void;
  onClick?: (product: Product) => void;
}

const extractErrorMessage = (err: any): string => {
  if (!err) return 'An unknown error occurred.';
  if (typeof err === 'string') return err;
  if (err instanceof Error) return err.message;
  if (typeof err === 'object') {
    if (err.message) return err.message;
    if (err.error_description) return err.error_description;
    try {
      const json = JSON.stringify(err);
      if (json !== '{}' && !json.includes('[object Object]')) return json;
    } catch { /* ignore */ }
  }
  return 'Failed to perform action.';
};

export const ProductCard: React.FC<ProductCardProps> = ({ product, onDelete, onClick }) => {
  const { addToCart, toggleWishlist, wishlist, user } = useStore();
  const [isDeleting, setIsDeleting] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();

  const isWishlisted = wishlist.includes(product.id);
  const isAdmin = user?.email && ADMIN_EMAILS.some(email => email.toLowerCase() === user.email?.toLowerCase());

  const imageUrl = product.image_urls && product.image_urls.length > 0 
    ? product.image_urls[0] 
    : `https://picsum.photos/seed/${product.id}/300/300`;

  const hasDiscount = product.discount && product.discount > 0;
  const finalPrice = hasDiscount 
    ? product.price * (1 - product.discount! / 100) 
    : product.price;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleDelete = async () => {
    if (!window.confirm('Are you sure you want to delete this product? This cannot be undone.')) {
      return;
    }

    setIsDeleting(true);
    try {
      const { error } = await supabase
        .from('products')
        .delete()
        .eq('id', product.id);

      if (error) throw error;

      if (onDelete) {
        onDelete(product.id);
      }
    } catch (error) {
      console.error('Error deleting product:', error);
      alert(`Delete failed: ${extractErrorMessage(error)}`);
    } finally {
      setIsDeleting(false);
      setShowMenu(false);
    }
  };

  const handleEdit = () => {
    navigate(`/admin/upload?id=${product.id}`);
    setShowMenu(false);
  };

  const handleCardClick = (e: React.MouseEvent) => {
    // Prevent opening modal if clicking admin buttons or action buttons
    const target = e.target as HTMLElement;
    if (target.closest('button')) return;

    if (onClick) {
      onClick(product);
    }
  };

  return (
    <div 
      className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden flex flex-col h-full hover:shadow-lg transition-all duration-300 relative group cursor-pointer"
      onClick={handleCardClick}
    >
      <div className="relative aspect-square bg-gray-50">
        <img 
          src={imageUrl} 
          alt={product.name} 
          className="w-full h-full object-cover object-center"
          loading="lazy"
        />

        {/* Discount Badge */}
        {hasDiscount && (
          <div className="absolute top-0 left-0 bg-orange-500 text-white text-xs font-bold px-2 py-1 rounded-br-lg shadow-sm z-10">
            -{product.discount}%
          </div>
        )}

        {/* Wishlist Button */}
        <button 
          onClick={(e) => {
            e.stopPropagation();
            e.preventDefault();
            toggleWishlist(product.id);
          }}
          className="absolute top-2 right-2 p-1.5 rounded-full bg-white/80 backdrop-blur-sm hover:bg-white transition text-gray-600 z-10"
        >
          <Heart className={`w-5 h-5 ${isWishlisted ? 'fill-red-500 text-red-500' : ''}`} />
        </button>

        {/* Admin Menu */}
        {isAdmin && (
          <div className="absolute top-2 left-2 z-20" ref={menuRef}>
            <button 
              onClick={(e) => {
                e.stopPropagation();
                setShowMenu(!showMenu);
              }}
              className="p-1.5 rounded-full bg-white/90 hover:bg-white text-gray-700 transition shadow-sm"
              title="Admin Options"
            >
              <MoreVertical className="w-4 h-4" />
            </button>

            {showMenu && (
              <div className="absolute top-full left-0 mt-1 w-32 bg-white rounded-lg shadow-xl border border-gray-100 overflow-hidden py-1 animate-in fade-in zoom-in duration-200">
                <button 
                  onClick={(e) => { e.stopPropagation(); handleEdit(); }}
                  className="w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2"
                >
                  <Edit className="w-3 h-3" /> Edit
                </button>
                <button 
                  onClick={(e) => { e.stopPropagation(); handleDelete(); }}
                  disabled={isDeleting}
                  className="w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-red-50 flex items-center gap-2"
                >
                  {isDeleting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Trash2 className="w-3 h-3" />}
                  Delete
                </button>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="p-3 flex flex-col flex-grow">
        <div className="flex justify-between items-start mb-1">
          <p className="text-xs text-secondary font-medium uppercase tracking-wide">{product.category}</p>
        </div>

        <h3 className="font-semibold text-gray-800 text-sm md:text-base line-clamp-2 mb-2 flex-grow group-hover:text-primary transition-colors">
          {product.name}
        </h3>

        {/* Colors Preview (Small dots) */}
        {product.colors && product.colors.length > 0 && (
          <div className="flex gap-1 mb-2">
            {product.colors.slice(0, 4).map((c, i) => (
              <div key={i} className="w-2 h-2 rounded-full bg-gray-200 border border-gray-300" title={c} />
            ))}
            {product.colors.length > 4 && <span className="text-[10px] text-gray-400">+{product.colors.length - 4}</span>}
          </div>
        )}

        <div className="mt-auto flex items-center justify-between">
          <div className="flex flex-col">
            <span className="text-lg font-bold text-primary">₦{finalPrice.toLocaleString(undefined, { maximumFractionDigits: 0 })}</span>
            {hasDiscount && (
              <span className="text-xs text-gray-400 line-through">₦{product.price.toLocaleString()}</span>
            )}
          </div>
          <button 
            onClick={(e) => {
              e.stopPropagation();
              // If product has colors, open modal instead of direct add
              if (product.colors && product.colors.length > 0 && onClick) {
                onClick(product);
              } else {
                addToCart(product);
              }
            }}
            className="p-2 bg-primary text-white rounded-lg hover:bg-blue-800 transition active:scale-95 shadow-md shadow-blue-900/10"
            aria-label="Add to cart"
          >
            <ShoppingBag className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { ProductCard } from '../components/ProductCard';
import { ProductDetailModal } from '../components/ProductDetailModal';
import { supabase } from '../lib/supabase';
import { Product, CATEGORIES } from '../types';
import { useStore } from '../store/useStore';
import { Loader2, AlertCircle, RefreshCw } from 'lucide-react';
import { useSearchParams } from 'react-router-dom';

const extractErrorMessage = (err: any): string => {
  if (!err) return 'An unknown error occurred.';
  if (typeof err === 'string') return err;
  if (err instanceof Error) return err.message;
  if (typeof err === 'object') {
    if (err.message) return err.message;
    if (err.error_description) return err.error_description;
    if (err.details) return err.details;
    if (err.hint) return err.hint;
    if (err.error && typeof err.error === 'object' && err.error.message) return err.error.message;
    try {
      const json = JSON.stringify(err);
      if (json !== '{}' && !json.includes('[object Object]')) {
        return `Error details: ${json}`;
      }
    } catch (e) { /* ignore */ }
  }
  return 'An unexpected error occurred. Please check your connection.';
};

export const Home: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<string>('All');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null); // State for Modal
  const { searchQuery } = useStore();
  const [searchParams] = useSearchParams();

  useEffect(() => {
    const categoryParam = searchParams.get('category');
    if (categoryParam) {
      setSelectedCategory(decodeURIComponent(categoryParam));
    }
  }, [searchParams]);

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    setLoading(true);
    setError(null);
    try {
      const { data, error: supabaseError } = await supabase
        .from('products')
        .select('*')
        .order('created_at', { ascending: false });

      if (supabaseError) {
        throw supabaseError;
      }

      setProducts(data || []);
    } catch (err: any) {
      console.error('Error fetching products:', err);
      const msg = extractErrorMessage(err);
      if (msg === 'Failed to fetch') {
        setError('Network error: Could not connect to Supabase. Please check your internet connection.');
      } else {
        setError(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const filteredProducts = products.filter(product => {
    const matchesSearch = product.name.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesCategory = selectedCategory === 'All' || product.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-center px-4">
        <div className="bg-red-50 p-4 rounded-full mb-4">
          <AlertCircle className="w-10 h-10 text-red-500" />
        </div>
        <h3 className="text-xl font-bold text-gray-800 mb-2">Connection Error</h3>
        <p className="text-gray-600 mb-6 max-w-md text-sm break-words">{error}</p>
        <button 
          onClick={fetchProducts}
          className="bg-primary text-white px-6 py-2.5 rounded-lg hover:bg-blue-800 transition flex items-center gap-2 shadow-sm"
        >
          <RefreshCw className="w-4 h-4" />
          Try Again
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-8 relative">
      {/* Product Detail Modal */}
      {selectedProduct && (
        <ProductDetailModal 
          product={selectedProduct} 
          onClose={() => setSelectedProduct(null)} 
        />
      )}

      {/* Hero Section */}
      {!searchQuery && selectedCategory === 'All' && (
        <div className="relative rounded-2xl overflow-hidden bg-primary text-white shadow-lg">
          <div className="absolute inset-0 bg-gradient-to-r from-blue-900/90 to-blue-600/50 z-10"></div>
          <div className="relative z-20 p-8 md:p-12 flex flex-col md:flex-row items-center justify-between gap-6">
            <div className="text-center md:text-left mb-6 md:mb-0 max-w-lg">
              <h2 className="text-3xl md:text-5xl font-bold mb-4">Baby Care & More</h2>
              <p className="text-blue-100 text-lg mb-6">Premium quality bags, shoes, and baby essentials delivered to your doorstep.</p>
              <button 
                onClick={() => setSelectedCategory('Diapers')}
                className="bg-white text-primary px-6 py-3 rounded-full font-bold hover:bg-blue-50 transition shadow-lg"
              >
                Shop Diapers
              </button>
            </div>
            <div className="w-full md:w-1/2 flex justify-center md:justify-end">
               <img 
                 src="baby.png" 
                 alt="Baby Care Collection" 
                 className="max-h-64 object-contain drop-shadow-2xl hover:scale-105 transition duration-500" 
               />
            </div>
          </div>
        </div>
      )}

      {/* Category Chips */}
      <div className="flex gap-3 overflow-x-auto no-scrollbar py-2 sticky top-[130px] md:top-20 z-30 bg-surface/95 backdrop-blur-sm">
        <button
          onClick={() => setSelectedCategory('All')}
          className={`whitespace-nowrap px-4 py-2 rounded-full text-sm font-medium transition ${
            selectedCategory === 'All' 
              ? 'bg-primary text-white shadow-md' 
              : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-50'
          }`}
        >
          All Items
        </button>
        {CATEGORIES.map(cat => (
          <button
            key={cat}
            onClick={() => setSelectedCategory(cat)}
            className={`whitespace-nowrap px-4 py-2 rounded-full text-sm font-medium transition ${
              selectedCategory === cat 
                ? 'bg-primary text-white shadow-md' 
                : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-50'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Product Grid */}
      {loading ? (
        <div className="flex justify-center items-center py-20">
          <Loader2 className="w-8 h-8 text-primary animate-spin" />
        </div>
      ) : (
        <>
          {selectedCategory === 'All' && !searchQuery ? (
             <div className="space-y-10">
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3 md:gap-6">
                  {filteredProducts.map(product => (
                    <ProductCard 
                      key={product.id} 
                      product={product} 
                      onDelete={handleDeleteProduct}
                      onClick={setSelectedProduct}
                    />
                  ))}
                </div>
                {filteredProducts.length === 0 && (
                  <div className="text-center py-10 text-gray-500">
                    No products found.
                  </div>
                )}
             </div>
          ) : (
            <div className="space-y-4">
               {selectedCategory !== 'All' && (
                  <h2 className="text-xl font-bold text-gray-800">{selectedCategory}</h2>
               )}
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3 md:gap-6">
                {filteredProducts.length > 0 ? (
                  filteredProducts.map(product => (
                    <ProductCard 
                      key={product.id} 
                      product={product} 
                      onDelete={handleDeleteProduct}
                      onClick={setSelectedProduct}
                    />
                  ))
                ) : (
                  <div className="col-span-full text-center py-10 text-gray-500">
                    {products.length === 0 ? "No products found in database." : `No products found in ${selectedCategory}.`}
                  </div>
                )}
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
};

