          onClick={fetchProducts}
          className="bg-primary text-white px-6 py-2.5 rounded-lg hover:bg-blue-800 transition flex items-center gap-2 shadow-sm"
        >
          <RefreshCw className="w-4 h-4" />
          Try Again
        </button>
      </div>
    );
