      {toasts.map((toast) => (
        <div
          key={toast.id}
          className={`pointer-events-auto w-full p-4 rounded-xl shadow-lg border flex items-start gap-3 animate-in slide-in-from-top-5 fade-in duration-300 ${
            toast.type === 'success' ? 'bg-white border-green-100 text-gray-800' :
            toast.type === 'error' ? 'bg-white border-red-100 text-gray-800' :
            'bg-white border-blue-100 text-gray-800'
          }`}
        >
          <div className={`mt-0.5 p-1 rounded-full ${
            toast.type === 'success' ? 'bg-green-100' :
            toast.type === 'error' ? 'bg-red-100' :
