  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Product, ADMIN_EMAILS } from '../types';
import { useStore } from '../store/useStore';
import { useToast } from '../store/useToast';
import { ShoppingCart, Heart, Trash2, Loader2, MoreVertical, Edit } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useNavigate } from 'react-router-dom';

interface ProductCardProps {
  product: Product;
  onDelete?: (id: string) => void;
  onClick?: (product: Product) => void;
}

const extractErrorMessage = (err: any): string => {
  if (!err) return 'An unknown error occurred.';
  if (typeof err === 'string') return err;
  if (err instanceof Error) return err.message;
  if (typeof err === 'object') {
    if (err.message) return err.message;
    if (err.error_description) return err.error_description;
    try {
      const json = JSON.stringify(err);
      if (json !== '{}' && !json.includes('[object Object]')) return json;
    } catch { /* ignore */ }
  }
  return 'Failed to perform action.';
};

export const ProductCard: React.FC<ProductCardProps> = ({ product, onDelete, onClick }) => {
  const { addToCart, toggleWishlist, wishlist, user } = useStore();
  const { addToast } = useToast();
  const [isDeleting, setIsDeleting] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();

  const isWishlisted = wishlist.includes(product.id);
  const isAdmin = user?.email && ADMIN_EMAILS.some(email => email.toLowerCase() === user.email?.toLowerCase());

  // Use logo.png as fallback if no product images exist
  const imageUrl = product.image_urls && product.image_urls.length > 0 
    ? product.image_urls[0] 
    : '/logo.png';

  const hasDiscount = product.discount && product.discount > 0;
  const finalPrice = hasDiscount 
    ? product.price * (1 - product.discount! / 100) 
    : product.price;

  const hasColors = product.colors && product.colors.length > 0;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleDelete = async () => {
    // Close menu immediately
    setShowMenu(false);

    if (!window.confirm('Are you sure you want to delete this product? This cannot be undone.')) {
      return;
    }

    setIsDeleting(true);
    try {
      const { error } = await supabase
        .from('products')
        .delete()
        .eq('id', product.id);

      if (error) throw error;

      addToast('Product deleted successfully', 'success');

      if (onDelete) {
        onDelete(product.id);
      }
    } catch (error) {
      console.error('Error deleting product:', error);
      addToast(`Delete failed: ${extractErrorMessage(error)}`, 'error');
      setIsDeleting(false);
    }
  };

  const handleEdit = () => {
    navigate(`/admin/upload?id=${product.id}`);
    setShowMenu(false);
  };

  const handleCardClick = (e: React.MouseEvent) => {
    const target = e.target as HTMLElement;
    // Prevent navigation if clicking buttons or menu items
    if (target.closest('button') || target.closest('[role="menuitem"]')) return;

    if (onClick) {
      onClick(product);
    }
  };

  const handleAddToCart = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (hasColors && onClick) {
      onClick(product);
    } else {
      addToCart(product);
      addToast('Added to cart', 'success');
    }
  };

  return (
    <div 
      className={`group bg-white rounded-2xl shadow-sm border border-gray-100 flex flex-col h-full hover:shadow-xl hover:-translate-y-1 transition-all duration-300 relative cursor-pointer ${showMenu ? 'z-50' : 'z-0'}`}
      onClick={handleCardClick}
    >
      {/* Loading Overlay for Deletion */}
      {isDeleting && (
        <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-[60] flex flex-col items-center justify-center rounded-2xl animate-in fade-in">
          <Loader2 className="w-8 h-8 text-red-500 animate-spin mb-2" />
          <span className="text-xs font-medium text-red-500">Deleting...</span>
        </div>
      )}

      {/* Admin Menu */}
      {isAdmin && (
        <div className="absolute top-3 left-3 z-30" ref={menuRef}>
          <button 
            onClick={(e) => {
              e.stopPropagation();
              setShowMenu(!showMenu);
            }}
            className="p-2 rounded-full bg-white/90 hover:bg-white text-gray-700 transition shadow-sm backdrop-blur-sm"
            title="Admin Options"
          >
            <MoreVertical className="w-4 h-4" />
          </button>

          {showMenu && (
            <div className="absolute top-full left-0 mt-1 w-36 bg-white rounded-lg shadow-xl border border-gray-100 overflow-hidden py-1 animate-in fade-in zoom-in duration-200 z-40" role="menu">
              <button 
                onClick={(e) => { e.stopPropagation(); handleEdit(); }}
                className="w-full text-left px-4 py-2.5 text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2"
                role="menuitem"
              >
                <Edit className="w-3 h-3" /> Edit
              </button>
              <button 
                onClick={(e) => { e.stopPropagation(); handleDelete(); }}
                disabled={isDeleting}
                className="w-full text-left px-4 py-2.5 text-sm text-red-600 hover:bg-red-50 flex items-center gap-2"
                role="menuitem"
              >
                <Trash2 className="w-3 h-3" />
                Delete
              </button>
            </div>
          )}
        </div>
      )}

      {/* Image Area */}
      <div className="relative aspect-square bg-gray-50 overflow-hidden rounded-t-2xl">
        <img 
          src={imageUrl} 
          alt={product.name} 
          className="w-full h-full object-cover object-center transition-transform duration-700 group-hover:scale-110"
          loading="lazy"
        />

        {/* Discount Badge */}
        {hasDiscount && (
          <div className="absolute top-3 left-3 bg-red-600 text-white text-[10px] font-bold px-2.5 py-1 rounded-full shadow-md z-10 animate-pulse pointer-events-none">
            -{product.discount}% OFF
          </div>
        )}

        {/* Wishlist Button */}
        <button 
          onClick={(e) => {
            e.stopPropagation();
            e.preventDefault();
            toggleWishlist(product.id);
            if (!isWishlisted) addToast("Added to wishlist", "success");
            else addToast("Removed from wishlist", "info");
          }}
          className="absolute top-3 right-3 p-2 rounded-full bg-white/90 backdrop-blur-sm hover:bg-white transition text-gray-400 hover:text-red-500 hover:shadow-sm z-10"
        >
          <Heart className={`w-5 h-5 ${isWishlisted ? 'fill-red-500 text-red-500' : ''}`} />
        </button>
      </div>

      {/* Content Area */}
      <div className="p-4 flex flex-col flex-grow relative z-0">
        <div className="flex justify-between items-start mb-1">
          <p className="text-[10px] md:text-xs text-gray-500 font-semibold uppercase tracking-wider">{product.category}</p>
        </div>

        <h3 className="font-medium text-gray-900 text-sm md:text-[15px] leading-snug line-clamp-2 mb-2 group-hover:text-primary transition-colors">
          {product.name}
        </h3>

        {/* Colors Preview */}
        {hasColors && (
          <div className="flex items-center gap-2 mb-3">
             <span className="text-[10px] text-gray-400 font-medium">Colors:</span>
             <div className="flex gap-1.5">
              {product.colors!.slice(0, 4).map((c, i) => (
                <div 
                  key={i} 
                  className="w-3 h-3 rounded-full border border-gray-300 shadow-sm" 
                  style={{ backgroundColor: c.toLowerCase().replace(' ', '') }} 
                  title={c} 
                />
              ))}
              {product.colors!.length > 4 && <span className="text-[10px] text-gray-400">+{product.colors!.length - 4}</span>}
             </div>
          </div>
        )}

        <div className="mt-auto flex items-center justify-between pt-2">
          <div className="flex flex-col">
            <span className={`text-lg font-bold ${hasDiscount ? 'text-red-600' : 'text-gray-900'}`}>
              ₦{finalPrice.toLocaleString(undefined, { maximumFractionDigits: 0 })}
            </span>
            {hasDiscount && (
              <span className="text-xs text-gray-400 line-through font-medium">₦{product.price.toLocaleString()}</span>
            )}
          </div>

          <button 
            onClick={handleAddToCart}
            className="w-10 h-10 rounded-full bg-blue-50 text-primary flex items-center justify-center hover:bg-primary hover:text-white transition-all duration-300 shadow-sm hover:shadow-md active:scale-95 group-hover:bg-primary group-hover:text-white"
            aria-label="Add to cart"
          >
            <ShoppingCart className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Product } from '../types';
import { useStore } from '../store/useStore';
import { useToast } from '../store/useToast';
import { X, ShoppingCart, Check, Heart, ShieldCheck, Truck } from 'lucide-react';

interface ProductDetailModalProps {
  product: Product;
  onClose: () => void;
}

export const ProductDetailModal: React.FC<ProductDetailModalProps> = ({ product, onClose }) => {
  const { addToCart, toggleWishlist, wishlist } = useStore();
  const { addToast } = useToast();
  const [selectedImageIndex, setSelectedImageIndex] = useState(0);
  const [selectedColor, setSelectedColor] = useState<string | undefined>(
    product.colors && product.colors.length > 0 ? product.colors[0] : undefined
  );

  const images = product.image_urls && product.image_urls.length > 0 
    ? product.image_urls 
    : [`/logo.png`];

  const hasDiscount = product.discount && product.discount > 0;
  const finalPrice = hasDiscount 
    ? product.price * (1 - product.discount! / 100) 
    : product.price;

  const isWishlisted = wishlist.includes(product.id);

  const handleAddToCart = () => {
    addToCart(product, selectedColor);
    addToast(`${product.name} added to cart!`, 'success');
    onClose();
  };

  const handleToggleWishlist = () => {
    toggleWishlist(product.id);
    if (!isWishlisted) {
      addToast("Added to wishlist", "success");
    } else {
      addToast("Removed from wishlist", "info");
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 md:p-6 animate-in fade-in duration-200">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      ></div>

      {/* Modal Content */}
      <div className="bg-white w-full md:w-full max-w-5xl max-h-[90vh] md:h-auto md:max-h-[85vh] rounded-2xl shadow-2xl relative flex flex-col md:flex-row z-10 animate-in zoom-in-95 duration-200 overflow-y-auto md:overflow-hidden">

        {/* Close Button */}
        <div className="absolute top-4 right-4 z-20">
          <button 
            onClick={onClose}
            className="p-2 bg-white/90 backdrop-blur-sm rounded-full hover:bg-gray-100 transition shadow-sm border border-gray-100"
          >
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        {/* Left Side: Images */}
        <div className="w-full md:w-1/2 bg-gray-50 flex flex-col flex-shrink-0">
          {/* Main Image */}
          <div className="relative h-72 sm:h-80 md:h-96 w-full flex-shrink-0 bg-gray-50">
            <img 
              src={images[selectedImageIndex]} 
              alt={product.name} 
              className="w-full h-full object-contain md:object-cover mix-blend-multiply md:mix-blend-normal"
            />
            {hasDiscount && (
              <div className="absolute top-4 left-4 bg-red-600 text-white font-bold px-3 py-1 rounded-full shadow-lg">
                -{product.discount}% OFF
              </div>
            )}
          </div>

          {/* Thumbnails */}
          <div className="p-4 flex gap-2 overflow-x-auto no-scrollbar justify-center bg-white border-t border-gray-100 min-h-[100px]">
            {images.map((img, idx) => (
              <button
                key={idx}
                onClick={() => setSelectedImageIndex(idx)}
                className={`w-16 h-16 rounded-lg border-2 overflow-hidden flex-shrink-0 transition ${
                  selectedImageIndex === idx ? 'border-primary ring-2 ring-primary/20' : 'border-transparent hover:border-gray-200'
                }`}
              >
                <img src={img} alt={`View ${idx + 1}`} className="w-full h-full object-cover" />
              </button>
            ))}
          </div>
        </div>

        {/* Right Side: Info */}
        <div className="w-full md:w-1/2 flex flex-col bg-white md:h-full md:overflow-y-auto">
          <div className="p-6 md:p-8 flex flex-col h-full relative">
            {/* Header */}
            <div className="mb-4 pr-8">
              <span className="text-sm font-medium text-primary bg-blue-50 px-2 py-1 rounded-md mb-2 inline-block">
                {product.category}
              </span>
              <h2 className="text-2xl font-bold text-gray-900 leading-tight mb-2">
                {product.name}
              </h2>

              {/* Price Block */}
              <div className="flex items-baseline gap-3 mt-3">
                <span className={`text-3xl font-bold ${hasDiscount ? 'text-red-600' : 'text-gray-900'}`}>
                  ₦{finalPrice.toLocaleString(undefined, { maximumFractionDigits: 0 })}
                </span>
                {hasDiscount && (
                  <span className="text-lg text-gray-400 line-through decoration-gray-400">
                    ₦{product.price.toLocaleString()}
                  </span>
                )}
              </div>
            </div>

            <hr className="border-gray-100 mb-6" />

            {/* Colors */}
            {product.colors && product.colors.length > 0 && (
              <div className="mb-6">
                <h3 className="text-sm font-semibold text-gray-900 mb-3 flex items-center justify-between">
                  Select Color
                  <span className="text-primary font-normal">{selectedColor}</span>
                </h3>
                <div className="flex flex-wrap gap-3">
                  {product.colors.map((color) => (
                    <button
                      key={color}
                      onClick={() => setSelectedColor(color)}
                      className={`px-4 py-2 rounded-full border transition flex items-center gap-2 ${
                        selectedColor === color 
                          ? 'border-primary bg-blue-50 text-primary font-medium ring-1 ring-primary' 
                          : 'border-gray-200 text-gray-600 hover:border-gray-300'
                      }`}
                    >
                      {selectedColor === color && <Check className="w-3 h-3" />}
                      {color}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Trust Badges */}
            <div className="grid grid-cols-2 gap-3 mb-6">
              <div className="flex items-center gap-2 text-xs text-gray-600 bg-gray-50 p-2 rounded-lg">
                <Truck className="w-4 h-4 text-green-600" />
                <span>Fast Delivery</span>
              </div>
              <div className="flex items-center gap-2 text-xs text-gray-600 bg-gray-50 p-2 rounded-lg">
                <ShieldCheck className="w-4 h-4 text-blue-600" />
                <span>Quality Guarantee</span>
              </div>
            </div>

            {/* Description */}
            <div className="mb-8 flex-grow">
              <h3 className="text-sm font-semibold text-gray-900 mb-2">Description</h3>
              <p className="text-gray-600 text-sm leading-relaxed whitespace-pre-wrap">
                {product.description}
              </p>
            </div>

            {/* Action Buttons - Sticky on mobile */}
            <div className="mt-auto pt-4 border-t border-gray-100 grid grid-cols-[auto_1fr] gap-4 sticky bottom-0 bg-white pb-2 md:static md:pb-0 z-10">
              <button 
                onClick={handleToggleWishlist}
                className={`p-4 rounded-xl border flex flex-col items-center justify-center gap-1 transition w-20 ${
                  isWishlisted 
                    ? 'border-red-200 bg-red-50 text-red-500' 
                    : 'border-gray-200 text-gray-400 hover:bg-gray-50'
                }`}
              >
                <Heart className={`w-6 h-6 ${isWishlisted ? 'fill-current' : ''}`} />
                <span className="text-[10px] font-medium">Save</span>
              </button>

              <button 
                onClick={handleAddToCart}
                disabled={product.colors && product.colors.length > 0 && !selectedColor}
                className="bg-primary hover:bg-blue-800 text-white rounded-xl font-bold text-lg shadow-xl shadow-blue-900/20 transition transform active:scale-[0.98] flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <ShoppingCart className="w-5 h-5" />
                Add to Cart
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

